/bin/bash -lc "cat > /tmp/menu-check.test.jsx <<'EOF'
import { describe, expect, it } from 'vitest';
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import React from 'react';
import { App } from './src/App';

describe('actions menu', () => {
  it('opens action list and selects an action', async () => {
    render(<App />);
    fireEvent.click(screen.getByRole('button', { name: 'Действия' }));
    expect(await screen.findByRole('menu')).toBeInTheDocument();
    fireEvent.click(screen.getByRole('menuitem', { name: 'Переименовать' }));
    await waitFor(() => expect(screen.getByText('Выбрано действие: Переименовать')).toBeInTheDocument());
    cleanup();
  });
});
EOF
npx vitest run /tmp/menu-check.test.jsx --root ."
